from funcy import memoize, cache, reraise
from funcy.calc import SkipMemoization

for decorator in (memoize, memoize(), cache(60)):
    calls = []
    @decorator
    def f(*args, **kwargs):
        calls.append((args, kwargs))
        return len(calls)
    assert f(1, a=2, b=3) == f(1, b=3, a=2) == 1
    assert f(2) == 2
    f.invalidate(1, b=3, a=2)
    f.invalidate(1, a=2, b=3)
    assert f(2) == 2
    assert f(1, a=2, b=3) == 3
    memory = f.memory
    f.invalidate_all()
    assert f.memory is memory and memory == {}
    assert f(2) == 4

for decorator in (memoize, cache):
    options = {} if decorator is memoize else {'timeout': 60}
    @decorator(key_func=lambda x, **kw: len(x), **options)
    def f(x, **kw):
        return x
    assert f('a') == f('b') == 'a'
    f.invalidate('c', unused=True)
    assert f('b') == 'b'
    @decorator(**options)
    def skipped(value=None):
        raise skipped.skip(value)
    assert skipped.skip is SkipMemoization
    assert skipped(42) == 42 and skipped() is None and not skipped.memory

original = ValueError('original')
replacement = RuntimeError('replacement')
seen = []
def transform(error):
    seen.append(error)
    return RuntimeError(str(error))
for into in (RuntimeError, replacement, transform):
    try:
        with reraise(ValueError, into):
            raise original
    except RuntimeError as error:
        assert error.__cause__ is original
        if into is RuntimeError:
            assert error.args == ()
        elif into is replacement:
            assert error is replacement
        else:
            assert error.args == ('original',)
assert seen == [original]

@reraise(ValueError, transform)
def fail():
    raise original
for _ in range(2):
    try:
        fail()
    except RuntimeError as error:
        assert error.__cause__ is original
assert seen == [original] * 3
print('Focused requirement checks passed')
